def transform(grid):
    # Remove the marked overlays: 8 and 0 are erased to the grid background;
    # isolated marker colors are likewise restored by surrounding area.
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v in (0,8,4,7):
                out[r][c]=9
    # Restore the interiors of the two 6 rectangles where marker 4 was embedded.
    for r,c in [(17,2),(18,4)]: out[r][c]=6
    return out
